"""Loads static prompt text once per process."""

from functools import lru_cache
from pathlib import Path

from config import PERSONA_PATH


def _read(path: Path) -> str:
    if not path.is_file():
        raise FileNotFoundError(f"Prompt asset not found: {path}")
    return path.read_text(encoding="utf-8").strip()


@lru_cache(maxsize=1)
def load_persona() -> str:
    """Return the agent persona text."""
    return _read(PERSONA_PATH)


def build_system_prompt(persona: str, policies: str) -> str:
    """Combine persona and policy text into a single provider-agnostic system prompt."""
    return (
        f"{persona}\n\n"
        "# Policy knowledge base\n\n"
        "The section below is your only authorized source for policy answers. "
        "If a policy question is not answered explicitly here, say you don't "
        "have the answer rather than guessing.\n\n"
        f"{policies}"
    )

"""Interface over the airline policy knowledge base."""

from functools import lru_cache
from pathlib import Path

from config import POLICIES_PATH


class PolicyKnowledgeBase:
    """Read-only access to policy text, independent of the backing store."""

    def __init__(self, path: Path) -> None:
        if not path.is_file():
            raise FileNotFoundError(f"Policy knowledge base not found: {path}")
        self._content = path.read_text(encoding="utf-8").strip()

    def search(self, query: str | None = None) -> str:
        """Return policy text relevant to the query.

        The corpus is small enough to pass whole; the query is accepted so a
        real retrieval implementation can replace this without changing callers.
        """
        return self._content


@lru_cache(maxsize=1)
def get_policy_kb() -> PolicyKnowledgeBase:
    """Return the process-wide policy knowledge base singleton."""
    return PolicyKnowledgeBase(POLICIES_PATH)

"""Mock booking lookup API."""

import re
from functools import lru_cache
from pathlib import Path
from typing import Any

from config import BOOKINGS_PATH
from connectors.base import LookupResult, LookupStatus, load_json_records

_BOOKING_REFERENCE_PATTERN = re.compile(r"^[A-Z0-9]{5,8}$")


class BookingsConnector:
    """Looks up passenger bookings, independent of the backing store."""

    def __init__(self, path: Path) -> None:
        self._records: list[dict[str, Any]] = load_json_records(path, "bookings")

    def find(self, booking_reference: str, last_name: str) -> LookupResult:
        """Find a booking by reference and passenger last name."""
        reference = booking_reference.strip().upper()
        surname = last_name.strip()

        if not _BOOKING_REFERENCE_PATTERN.match(reference):
            return LookupResult(
                status=LookupStatus.INVALID_INPUT,
                message=(
                    "Booking reference must be 5-8 letters or digits, "
                    f"got {booking_reference!r}."
                ),
            )
        if not surname:
            return LookupResult(
                status=LookupStatus.INVALID_INPUT,
                message="Last name must not be empty.",
            )

        for record in self._records:
            same_reference = record["booking_reference"].upper() == reference
            same_surname = record["last_name"].casefold() == surname.casefold()
            if same_reference and same_surname:
                return LookupResult(status=LookupStatus.FOUND, record=record)

        return LookupResult(
            status=LookupStatus.NOT_FOUND,
            message="No booking matches that reference and last name.",
            details={"booking_reference": reference, "last_name": surname},
        )


@lru_cache(maxsize=1)
def get_bookings_connector() -> BookingsConnector:
    """Return the process-wide bookings connector singleton."""
    return BookingsConnector(BOOKINGS_PATH)

"""Mock flight information API."""

import re
from datetime import date
from functools import lru_cache
from pathlib import Path
from typing import Any

from config import FLIGHTS_PATH
from connectors.base import LookupResult, LookupStatus, load_json_records

_FLIGHT_NUMBER_PATTERN = re.compile(r"^[A-Z]{2}\d{1,4}$")


class FlightsConnector:
    """Looks up flight status, independent of the backing store."""

    def __init__(self, path: Path) -> None:
        self._records: list[dict[str, Any]] = load_json_records(path, "flights")

    def find(self, flight_number: str, flight_date: str) -> LookupResult:
        """Find a flight by number and ISO date."""
        number = flight_number.strip().upper().replace(" ", "")
        day = flight_date.strip()

        if not _FLIGHT_NUMBER_PATTERN.match(number):
            return LookupResult(
                status=LookupStatus.INVALID_INPUT,
                message=(
                    "Flight number must be two letters followed by 1-4 digits, "
                    f"got {flight_number!r}."
                ),
            )
        try:
            date.fromisoformat(day)
        except ValueError:
            return LookupResult(
                status=LookupStatus.INVALID_INPUT,
                message=f"Date must be in YYYY-MM-DD format, got {flight_date!r}.",
            )

        for record in self._records:
            if record["flight_number"].upper() == number and record["date"] == day:
                return LookupResult(status=LookupStatus.FOUND, record=record)

        return LookupResult(
            status=LookupStatus.NOT_FOUND,
            message="No flight matches that number and date.",
            details={"flight_number": number, "date": day},
        )


@lru_cache(maxsize=1)
def get_flights_connector() -> FlightsConnector:
    """Return the process-wide flights connector singleton."""
    return FlightsConnector(FLIGHTS_PATH)

"""Provider-agnostic LLM interface and message types."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class Role(str, Enum):
    """Author of a transcript message."""

    USER = "user"
    ASSISTANT = "assistant"


@dataclass(frozen=True)
class ToolCall:
    """A tool invocation requested by the model."""

    id: str
    name: str
    arguments: dict[str, Any]


@dataclass(frozen=True)
class ToolResult:
    """The outcome of a tool invocation, returned to the model."""

    tool_call_id: str
    name: str
    content: dict[str, Any]


@dataclass(frozen=True)
class Message:
    """One transcript entry.

    An assistant message may carry text, tool calls, or both. A user message
    carries either text typed by the passenger or results from tool calls.
    """

    role: Role
    text: str | None = None
    tool_calls: tuple[ToolCall, ...] = ()
    tool_results: tuple[ToolResult, ...] = ()


@dataclass(frozen=True)
class ToolSchema:
    """Provider-agnostic description of a callable tool."""

    name: str
    description: str
    input_schema: dict[str, Any]


@dataclass(frozen=True)
class ProviderResponse:
    """Normalized model response."""

    text: str | None = None
    tool_calls: tuple[ToolCall, ...] = field(default_factory=tuple)

    @property
    def has_tool_calls(self) -> bool:
        return bool(self.tool_calls)


class ProviderError(RuntimeError):
    """Raised when a provider request fails or returns an unusable response."""


class LLMProvider(ABC):
    """Contract every LLM backend must satisfy."""

    @abstractmethod
    def chat(
        self,
        messages: list[Message],
        tools: list[ToolSchema],
        system: str,
        model: str,
    ) -> ProviderResponse:
        """Send a conversation turn and return the normalized response."""

"""Anthropic Messages API adapter."""

import json
from typing import Any

import anthropic

from config import MAX_TOKENS, REQUEST_TIMEOUT_SECONDS
from providers.base import (
    LLMProvider,
    Message,
    ProviderError,
    ProviderResponse,
    Role,
    ToolCall,
    ToolSchema,
)


class AnthropicProvider(LLMProvider):
    """Talks to Claude through Anthropic's native Messages API."""

    def __init__(self, api_key: str) -> None:
        self._client = anthropic.Anthropic(
            api_key=api_key, timeout=REQUEST_TIMEOUT_SECONDS
        )

    def chat(
        self,
        messages: list[Message],
        tools: list[ToolSchema],
        system: str,
        model: str,
    ) -> ProviderResponse:
        try:
            response = self._client.messages.create(
                model=model,
                max_tokens=MAX_TOKENS,
                system=self._build_system(system),
                tools=[self._to_tool_param(tool) for tool in tools],
                messages=self._to_wire_messages(messages),
            )
        except anthropic.APIError as exc:
            raise ProviderError(f"Anthropic request failed: {exc}") from exc

        return self._to_provider_response(response)

    @staticmethod
    def _build_system(system: str) -> list[dict[str, Any]]:
        # Cache hits are best-effort: Anthropic's ephemeral cache TTL is minutes,
        # so an idle CLI turn may miss it. Correctness never depends on a hit.
        return [
            {
                "type": "text",
                "text": system,
                "cache_control": {"type": "ephemeral"},
            }
        ]

    @staticmethod
    def _to_tool_param(tool: ToolSchema) -> dict[str, Any]:
        return {
            "name": tool.name,
            "description": tool.description,
            "input_schema": tool.input_schema,
        }

    @staticmethod
    def _to_wire_messages(messages: list[Message]) -> list[dict[str, Any]]:
        wire: list[dict[str, Any]] = []
        for message in messages:
            blocks: list[dict[str, Any]] = []
            if message.text:
                blocks.append({"type": "text", "text": message.text})
            for call in message.tool_calls:
                blocks.append(
                    {
                        "type": "tool_use",
                        "id": call.id,
                        "name": call.name,
                        "input": call.arguments,
                    }
                )
            for result in message.tool_results:
                blocks.append(
                    {
                        "type": "tool_result",
                        "tool_use_id": result.tool_call_id,
                        "content": json.dumps(result.content),
                    }
                )
            if blocks:
                wire.append({"role": message.role.value, "content": blocks})
        return wire

    @staticmethod
    def _to_provider_response(response: Any) -> ProviderResponse:
        text_parts: list[str] = []
        tool_calls: list[ToolCall] = []

        for block in response.content:
            block_type = getattr(block, "type", None)
            if block_type == "text":
                text_parts.append(block.text)
            elif block_type == "tool_use":
                arguments = block.input if isinstance(block.input, dict) else {}
                tool_calls.append(
                    ToolCall(id=block.id, name=block.name, arguments=arguments)
                )

        text = "\n".join(part for part in text_parts if part.strip()) or None
        return ProviderResponse(text=text, tool_calls=tuple(tool_calls))


__all__ = ["AnthropicProvider", "Role"]

"""OpenRouter (OpenAI-compatible) API adapter."""

import json
from typing import Any

import requests

from config import MAX_TOKENS, OPENROUTER_BASE_URL, REQUEST_TIMEOUT_SECONDS
from providers.base import (
    LLMProvider,
    Message,
    ProviderError,
    ProviderResponse,
    Role,
    ToolCall,
    ToolSchema,
)


class OpenRouterProvider(LLMProvider):
    """Talks to Claude through OpenRouter's OpenAI-compatible endpoint."""

    def __init__(self, api_key: str, base_url: str = OPENROUTER_BASE_URL) -> None:
        self._api_key = api_key
        self._url = f"{base_url.rstrip('/')}/chat/completions"

    def chat(
        self,
        messages: list[Message],
        tools: list[ToolSchema],
        system: str,
        model: str,
    ) -> ProviderResponse:
        payload = {
            "model": model,
            "max_tokens": MAX_TOKENS,
            "messages": [
                self._build_system_message(system),
                *self._to_wire_messages(messages),
            ],
            "tools": [self._to_tool_param(tool) for tool in tools],
        }
        headers = {
            "Authorization": f"Bearer {self._api_key}",
            "Content-Type": "application/json",
        }

        try:
            with requests.post(
                self._url,
                headers=headers,
                json=payload,
                timeout=REQUEST_TIMEOUT_SECONDS,
            ) as response:
                response.raise_for_status()
                body = response.json()
        except requests.RequestException as exc:
            raise ProviderError(f"OpenRouter request failed: {exc}") from exc
        except ValueError as exc:
            raise ProviderError("OpenRouter returned a non-JSON response") from exc

        return self._to_provider_response(body)

    @staticmethod
    def _build_system_message(system: str) -> dict[str, Any]:
        # cache_control pass-through to Claude is best-effort here; OpenRouter may
        # ignore it, which costs cache savings but changes nothing functionally.
        return {
            "role": "system",
            "content": [
                {
                    "type": "text",
                    "text": system,
                    "cache_control": {"type": "ephemeral"},
                }
            ],
        }

    @staticmethod
    def _to_tool_param(tool: ToolSchema) -> dict[str, Any]:
        return {
            "type": "function",
            "function": {
                "name": tool.name,
                "description": tool.description,
                "parameters": tool.input_schema,
            },
        }

    @staticmethod
    def _to_wire_messages(messages: list[Message]) -> list[dict[str, Any]]:
        wire: list[dict[str, Any]] = []
        for message in messages:
            if message.tool_results:
                wire.extend(
                    {
                        "role": "tool",
                        "tool_call_id": result.tool_call_id,
                        "content": json.dumps(result.content),
                    }
                    for result in message.tool_results
                )
                continue

            if message.role is Role.ASSISTANT:
                entry: dict[str, Any] = {
                    "role": "assistant",
                    "content": message.text or "",
                }
                if message.tool_calls:
                    entry["tool_calls"] = [
                        {
                            "id": call.id,
                            "type": "function",
                            "function": {
                                "name": call.name,
                                "arguments": json.dumps(call.arguments),
                            },
                        }
                        for call in message.tool_calls
                    ]
                wire.append(entry)
            elif message.text:
                wire.append({"role": "user", "content": message.text})
        return wire

    @staticmethod
    def _to_provider_response(body: dict[str, Any]) -> ProviderResponse:
        choices = body.get("choices")
        if not choices:
            raise ProviderError("OpenRouter response contained no choices")

        message = choices[0].get("message", {})
        text = message.get("content") or None
        tool_calls: list[ToolCall] = []

        for raw_call in message.get("tool_calls") or []:
            function = raw_call.get("function", {})
            raw_arguments = function.get("arguments") or "{}"
            try:
                arguments = json.loads(raw_arguments)
            except json.JSONDecodeError:
                arguments = {}
            if not isinstance(arguments, dict):
                arguments = {}
            tool_calls.append(
                ToolCall(
                    id=raw_call.get("id", ""),
                    name=function.get("name", ""),
                    arguments=arguments,
                )
            )

        return ProviderResponse(text=text, tool_calls=tuple(tool_calls))

"""Selects the configured LLM provider."""

from config import (
    ANTHROPIC_API_KEY,
    ANTHROPIC_MODEL,
    OPENROUTER_API_KEY,
    OPENROUTER_MODEL,
    ProviderName,
)
from providers.base import LLMProvider


def build_provider(name: ProviderName) -> LLMProvider:
    """Instantiate the adapter for the named provider."""
    if name == "anthropic":
        from providers.anthropic_provider import AnthropicProvider

        return AnthropicProvider(api_key=ANTHROPIC_API_KEY)
    if name == "openrouter":
        from providers.openrouter_provider import OpenRouterProvider

        return OpenRouterProvider(api_key=OPENROUTER_API_KEY)
    raise ValueError(f"Unknown provider: {name!r}")


def resolve_model(name: ProviderName) -> str:
    """Return the model identifier for the named provider."""
    if name == "anthropic":
        return ANTHROPIC_MODEL
    if name == "openrouter":
        return OPENROUTER_MODEL
    raise ValueError(f"Unknown provider: {name!r}")

"""Decorator-based registry for LLM-callable tools."""

from collections.abc import Callable
from typing import Any

from providers.base import ToolSchema

ToolHandler = Callable[..., dict[str, Any]]

_HANDLERS: dict[str, ToolHandler] = {}
_SCHEMAS: dict[str, ToolSchema] = {}


def register_tool(
    name: str, schema: dict[str, Any]
) -> Callable[[ToolHandler], ToolHandler]:
    """Register a handler under `name` with its JSON input schema."""

    def decorator(handler: ToolHandler) -> ToolHandler:
        if name in _HANDLERS:
            raise ValueError(f"Tool already registered: {name}")
        description = (handler.__doc__ or "").strip()
        if not description:
            raise ValueError(f"Tool {name} needs a docstring for its description")
        _HANDLERS[name] = handler
        _SCHEMAS[name] = ToolSchema(
            name=name, description=description, input_schema=schema
        )
        return handler

    return decorator


def get_tool_schemas() -> list[ToolSchema]:
    """Return schemas for every registered tool."""
    return list(_SCHEMAS.values())


def dispatch(name: str, arguments: dict[str, Any]) -> dict[str, Any]:
    """Invoke a registered tool, returning a JSON-serializable payload."""
    handler = _HANDLERS.get(name)
    if handler is None:
        return {"status": "error", "message": f"Unknown tool: {name}"}
    try:
        return handler(**arguments)
    except TypeError as exc:
        return {"status": "invalid_input", "message": f"Bad arguments for {name}: {exc}"}

"""Booking lookup tool."""

from typing import Any

from connectors import get_bookings_connector
from tools.registry import register_tool

SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "booking_reference": {
            "type": "string",
            "description": "The 6-character booking reference, e.g. MR7QX2.",
