{"filePath":"/Users/mikehirawady/Documents/Testing/chatbot-demo/session.py","content":""""In-memory transcript for a single conversation."""

from dataclasses import dataclass, field

from providers.base import Message, Role, ToolCall, ToolResult


@dataclass
class Session:
    """Holds one conversation's messages. Nothing survives a reset."""

    messages: list[Message] = field(default_factory=list)

    def add_user_text(self, text: str) -> None:
        self.messages.append(Message(role=Role.USER, text=text))

    def add_assistant_turn(
        self, text: str | None, tool_calls: tuple[ToolCall, ...] = ()
    ) -> None:
        self.messages.append(
            Message(role=Role.ASSISTANT, text=text, tool_calls=tool_calls)
        )

    def add_tool_results(self, results: tuple[ToolResult, ...]) -> None:
        self.messages.append(Message(role=Role.USER, tool_results=results))

    def snapshot(self) -> list[Message]:
        """Return a copy of the transcript for sending to a provider."""
        return list(self.messages)


def new_session() -> Session:
    """Start a fresh conversation with no prior history."""
    return Session()
"}

{"filePath":"/Users/mikehirawady/Documents/Testing/chatbot-demo/orchestration.py","content":""""Provider-agnostic conversation orchestration."""

from dataclasses import dataclass
from enum import Enum

from config import (
    CLOSING_LINE,
    EXIT_COMMANDS,
    MAX_TOOL_ROUNDTRIPS,
    RESET_PHRASES,
    TOOL_LIMIT_MESSAGE,
)
from knowledge_base import get_policy_kb
from prompt_loader import build_system_prompt, load_persona
from providers.base import (
    LLMProvider,
    ProviderError,
    ToolCall,
    ToolResult,
)
from session import Session, new_session
from tools import END_CONVERSATION_TOOL, dispatch, get_tool_schemas


class TurnOutcome(str, Enum):
    """What the CLI should do after a turn."""

    CONTINUE = "continue"
    RESET = "reset"
    EXIT = "exit"


@dataclass(frozen=True)
class TurnResult:
    """Reply to show the passenger, plus the resulting control action."""

    reply: str | None
    outcome: TurnOutcome


def is_exit_command(user_input: str) -> bool:
    """True when the passenger typed a literal command to quit the CLI."""
    return user_input.strip().casefold() in EXIT_COMMANDS


def wants_reset(user_input: str) -> bool:
    """Deterministic backstop for when the model doesn't call end_conversation."""
    normalized = user_input.casefold()
    return any(phrase in normalized for phrase in RESET_PHRASES)


class Orchestrator:
    """Runs conversation turns against any LLM provider."""

    def __init__(self, provider: LLMProvider, model: str) -> None:
        self._provider = provider
        self._model = model
        self._system = build_system_prompt(load_persona(), get_policy_kb().search())
        self._tools = get_tool_schemas()
        self._session = new_session()

    @property
    def session(self) -> Session:
        return self._session

    def reset(self) -> None:
        """Drop the transcript. Static assets and the system prompt are reused."""
        self._session = new_session()

    def handle_input(self, user_input: str) -> TurnResult:
        """Process one line of passenger input."""
        if is_exit_command(user_input):
            return TurnResult(reply=None, outcome=TurnOutcome.EXIT)

        if wants_reset(user_input):
            self.reset()
            return TurnResult(reply=CLOSING_LINE, outcome=TurnOutcome.RESET)

        self._session.add_user_text(user_input)
        return self._run_turn()

    def _run_turn(self) -> TurnResult:
        for _ in range(MAX_TOOL_ROUNDTRIPS):
            try:
                response = self._provider.chat(
                    messages=self._session.snapshot(),
                    tools=self._tools,
                    system=self._system,
                    model=self._model,
                )
            except ProviderError as exc:
                return TurnResult(reply=f"Sorry — {exc}", outcome=TurnOutcome.CONTINUE)

            self._session.add_assistant_turn(response.text, response.tool_calls)

            if not response.has_tool_calls:
                return TurnResult(reply=response.text, outcome=TurnOutcome.CONTINUE)

            if any(call.name == END_CONVERSATION_TOOL for call in response.tool_calls):
                self.reset()
                return TurnResult(reply=CLOSING_LINE, outcome=TurnOutcome.RESET)

            self._session.add_tool_results(self._run_tools(response.tool_calls))

        return TurnResult(reply=TOOL_LIMIT_MESSAGE, outcome=TurnOutcome.CONTINUE)

    @staticmethod
    def _run_tools(tool_calls: tuple[ToolCall, ...]) -> tuple[ToolResult, ...]:
        return tuple(
            ToolResult(
                tool_call_id=call.id,
                name=call.name,
                content=dispatch(call.name, call.arguments),
            )
            for call in tool_calls
        )
"}

{"filePath":"/Users/mikehirawady/Documents/Testing/chatbot-demo/cli.py","content":""""Interactive CLI for the Meridian Airlines customer service agent."""

import sys

from config import ACTIVE_PROVIDER
from orchestration import Orchestrator, TurnOutcome
from providers import build_provider, resolve_model

BANNER = """Meridian Airlines — customer service assistant
Provider: {provider} ({model})

Type your question, or "exit" to quit.
"""


def _print_reply(reply: str | None) -> None:
    if reply:
        print(f"\nAvery: {reply}\n")


def main() -> int:
    provider_name = ACTIVE_PROVIDER
    model = resolve_model(provider_name)
    orchestrator = Orchestrator(build_provider(provider_name), model)

    print(BANNER.format(provider=provider_name, model=model))

    while True:
        try:
            user_input = input("You: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nGoodbye.")
            return 0

        if not user_input:
            continue

        result = orchestrator.handle_input(user_input)
        _print_reply(result.reply)

        if result.outcome is TurnOutcome.EXIT:
            print("Goodbye.")
            return 0
        if result.outcome is TurnOutcome.RESET:
            print("— new conversation —\n")


if __name__ == "__main__":
    sys.exit(main())
"}

